#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll modpow(ll a,ll e,ll m){ll r=1;a%=m;while(e){if(e&1)r=r*a%m;a=a*a%m;e>>=1;}return r;}
int main(){
    ll nA,nB,p; scanf("%lld %lld %lld",&nA,&nB,&p);
    ll prodA=1,prodB=1,cA=0,cB=0;
    for(ll i=2;i<=nA;i++){
        ll a=(i+nB-1)%p;
        prodA=prodA*a%p;
        cA=(cA+modpow(a,p-2,p))%p;
    }
    for(ll j=2;j<=nB;j++){
        ll b=(j+nA-1)%p;
        prodB=prodB*b%p;
        cB=(cB+modpow(b,p-2,p))%p;
    }
    ll inner=((1 - cA*cB%p)%p+p)%p;
    ll ans=prodA*prodB%p*inner%p;
    printf("%lld\n",ans);
    return 0;
}
